fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n >= 4 {
                // If n >= 4, we only need to add 0 if n is already even,
                // or 1 if n is odd (so that n + x becomes even).
                n % 2
            } else {
                // If n < 4, we need to add enough to reach 4.
                4 - n
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_solve_various() {
        // All inputs are >= 2 by problem statement
        let queries = vec![2, 3, 4, 5, 6, 7, 8, 9];
        // f(2) = 4 - 2 = 2
        // f(3) = 4 - 3 = 1
        // f(4) = 4 mod 2 = 0
        // f(5) = 5 mod 2 = 1
        // f(6) = 6 mod 2 = 0
        // f(7) = 7 mod 2 = 1
        // f(8) = 8 mod 2 = 0
        // f(9) = 9 mod 2 = 1
        let expected = vec![2, 1, 0, 1, 0, 1, 0, 1];
        assert_eq!(solve(queries), expected);
    }

    #[test]
    fn test_solve_minimums() {
        // Edge cases at the lower bound
        assert_eq!(solve(vec![2]), vec![2]);
        assert_eq!(solve(vec![3]), vec![1]);
    }
}